import { useEffect } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import SingleResult from '../components/SingleResult'

export default function ResultPage() {
  const { state } = useLocation()
  const navigate  = useNavigate()

  // Restore scroll position after returning from user detail page
  useEffect(() => {
    const savedY = sessionStorage.getItem('resultScrollY')
    if (savedY) {
      window.scrollTo(0, parseInt(savedY, 10))
      sessionStorage.removeItem('resultScrollY')
    }
  }, [])

  useEffect(() => {
    if (!state?.result) navigate('/')
  }, [state, navigate])

  const result = state?.result
  if (!result) return null

  // ── Batch CSV mode ────────────────────────────────────────────────────────
  if (Array.isArray(result.results)) {
    const rows = result.results

    function handleRowClick(r) {
      sessionStorage.setItem('resultScrollY', String(window.scrollY))
      navigate('/result/user', { state: { row: r, from: state } })
    }

    return (
      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/')}>
            ← Back to Analysis
          </button>
          <span style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>
            CSV Batch &mdash; <strong style={{ color: 'var(--text-dim)' }}>{result.total_records ?? rows.length}</strong> scanned
            &nbsp;·&nbsp;
            <strong style={{ color: '#e55' }}>{rows.length}</strong> malicious flagged
            {result.saved_at && (
              <span style={{ marginLeft: '0.75rem', opacity: 0.5, fontSize: '0.75rem' }}>
                saved {new Date(result.saved_at).toLocaleString()}
              </span>
            )}
          </span>
        </div>

        <div className="card" style={{ marginBottom: '1.5rem', padding: 0, overflow: 'hidden' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.85rem' }}>
            <thead>
              <tr style={{ background: 'var(--surface)', borderBottom: '1px solid var(--border)' }}>
                {['Rank', 'Verdict', 'Threat Score', 'High', 'Med', 'Low', 'CSV Row', ''].map(h => (
                  <th key={h} style={{ padding: '0.65rem 1rem', textAlign: 'left', color: 'var(--text-dim)', fontWeight: 600 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => {
                const mal       = r.prediction === 1
                const threatPct = (r.probability * 100).toFixed(1)
                return (
                  <tr
                    key={i}
                    onClick={() => handleRowClick(r)}
                    style={{ borderBottom: '1px solid var(--border)', cursor: 'pointer', transition: 'background 0.15s' }}
                    onMouseEnter={e => e.currentTarget.style.background = 'var(--surface)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                  >
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--gold)', fontWeight: 700 }}>#{r.rank}</td>
                    <td style={{ padding: '0.6rem 1rem' }}>
                      <span style={{
                        display: 'inline-block',
                        padding: '0.2rem 0.6rem',
                        borderRadius: '4px',
                        fontSize: '0.75rem',
                        fontWeight: 700,
                        background: mal ? 'rgba(220,50,50,0.15)' : 'rgba(50,200,100,0.15)',
                        color: mal ? '#e55' : '#5c5',
                      }}>
                        {mal ? 'MALICIOUS' : 'NORMAL'}
                      </span>
                    </td>
                    <td style={{ padding: '0.6rem 1rem' }}>
                      <span style={{ color: mal ? '#e55' : 'var(--text)', fontWeight: mal ? 700 : 400 }}>
                        {threatPct}%
                      </span>
                    </td>
                    <td style={{ padding: '0.6rem 1rem', color: '#e55' }}>{r.high_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: '#fa0' }}>{r.medium_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--text-dim)' }}>{r.low_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--text-dim)', fontSize: '0.75rem' }}>{r.row_index}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--gold)', fontSize: '0.75rem', whiteSpace: 'nowrap' }}>
                      View →
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      </div>
    )
  }

  // ── Single result mode ────────────────────────────────────────────────────
  return <SingleResult result={result} onBack={() => navigate('/')} />
}
